import type { GeoJsonFeature, HereMapsViewRef, LatLng } from "expo-here-maps";
import { type RefObject, useCallback, useEffect, useRef, useState } from "react";

const DEBOUNCE_MS = 250;
const LONDON: LatLng = { lat: 51.5074, lng: -0.1278 };

export function useSearch(
	mapRef: RefObject<HereMapsViewRef | null>,
	userLocation: LatLng | null,
) {
	const [query, setQueryState] = useState("");
	const [results, setResults] = useState<GeoJsonFeature[]>([]);
	const [isLoading, setIsLoading] = useState(false);
	const [hasSearched, setHasSearched] = useState(false);

	const debounceRef = useRef<ReturnType<typeof setTimeout> | null>(null);
	const latestQuery = useRef("");

	const runSearch = useCallback(
		async (q: string) => {
			const ref = mapRef.current;
			if (!ref) return;

			setIsLoading(true);
			try {
				const near = userLocation ?? LONDON;
				const collection = await ref.suggestPlaces(q, near);
				if (latestQuery.current !== q) return;
				setResults(collection.features);
				setHasSearched(true);
			} catch (e) {
				if (latestQuery.current === q) {
					setResults([]);
					setHasSearched(true);
				}
			} finally {
				if (latestQuery.current === q) setIsLoading(false);
			}
		},
		[mapRef, userLocation],
	);

	const setQuery = useCallback(
		(q: string) => {
			setQueryState(q);
			latestQuery.current = q;
			if (debounceRef.current) clearTimeout(debounceRef.current);

			if (!q.trim()) {
				setResults([]);
				setHasSearched(false);
				setIsLoading(false);
				return;
			}

			debounceRef.current = setTimeout(() => runSearch(q), DEBOUNCE_MS);
		},
		[runSearch],
	);

	const clear = useCallback(() => {
		if (debounceRef.current) clearTimeout(debounceRef.current);
		latestQuery.current = "";
		setQueryState("");
		setResults([]);
		setHasSearched(false);
		setIsLoading(false);
	}, []);

	useEffect(() => {
		return () => {
			if (debounceRef.current) clearTimeout(debounceRef.current);
		};
	}, []);

	return { query, setQuery, results, isLoading, hasSearched, clear };
}

