1	import { useCurrentLocation } from "@/features/location/use-current-location";
2	import type {
3		GeoJsonFeature,
4		HereMapsViewRef,
5		LatLng,
6		RouteSummary,
7	} from "expo-here-maps";
8	import { type RefObject, useCallback, useState } from "react";
9	import { useSearch } from "./use-search";
10	
11	export type RoutePoint = {
12		label: string;
13		coords: LatLng | null;
14		isCurrentLocation: boolean;
15	};
16	
17	export type ActiveField = "origin" | "destination" | null;
18	
19	const CURRENT_LOCATION: RoutePoint = {
20		label: "Current location",
21		coords: null,
22		isCurrentLocation: true,
23	};
24	
25	export function useRouteSearch(mapRef: RefObject<HereMapsViewRef | null>) {
26		const userLocation = useCurrentLocation();
27		const [origin, setOrigin] = useState<RoutePoint>(CURRENT_LOCATION);
28		const [destination, setDestination] = useState<RoutePoint | null>(null);
29		const [active, setActive] = useState<ActiveField>("destination");
30		const [routeSummary, setRouteSummary] = useState<RouteSummary | null>(null);
31		const [isNavigating, setIsNavigating] = useState(false);
32	
33		const search = useSearch(mapRef, userLocation);
34	
35		const resolvedOrigin = origin.isCurrentLocation
36			? userLocation
37			: origin.coords;
38		const resolvedDestination = destination?.isCurrentLocation
39			? userLocation
40			: (destination?.coords ?? null);
41	
42		const canRoute = !!resolvedOrigin && !!resolvedDestination;
43	
44		const editField = useCallback(
45			(field: Exclude<ActiveField, null>) => {
46				setActive(field);
47				const point = field === "origin" ? origin : destination;
48				search.setQuery(point && !point.isCurrentLocation ? point.label : "");
49			},
50			[origin, destination, search],
51		);
52	
53		const selectResult = useCallback(
54			async (feature: GeoJsonFeature) => {
55				const coords = await mapRef.current?.resolvePlace(
56					feature.properties.placeId,
57				);
58				if (!coords) return;
59	
60				const point: RoutePoint = {
61					label: feature.properties.title,
62					coords,
63					isCurrentLocation: false,
64				};
65	
66				if (active === "origin") {
67					setOrigin(point);
68					setActive(destination ? null : "destination");
69				} else {
70					setDestination(point);
71					setActive(origin.coords || origin.isCurrentLocation ? null : "origin");
72				}
73				search.clear();
74			},
75			[active, origin, destination, mapRef, search],
76		);
77	
78		const setFieldToCurrent = useCallback(
79			(field: Exclude<ActiveField, null>) => {
80				if (field === "origin") setOrigin(CURRENT_LOCATION);
81				else setDestination(CURRENT_LOCATION);
82				setActive(null);
83				search.clear();
84			},
85			[search],
86		);
87	
88		const clearField = useCallback(
89			(field: Exclude<ActiveField, null>) => {
90				if (field === "origin") setOrigin(CURRENT_LOCATION);
91				else setDestination(null);
92				setRouteSummary(null);
93				search.setQuery("");
94			},
95			[search],
96		);
97	
98		const swap = useCallback(() => {
99			if (!destination && origin.isCurrentLocation) return;
100			const newOrigin: RoutePoint = destination ?? CURRENT_LOCATION;
101			const newDestination: RoutePoint = origin;
102			setOrigin(newOrigin);
103			setDestination(newDestination);
104			setActive(null);
105			setRouteSummary(null);
106		}, [origin, destination]);
107	
108		const confirmRoute = useCallback(async () => {
109			if (!resolvedOrigin || !resolvedDestination) return false;
110			try {
111				const summary = await mapRef.current?.showRoute(
112					resolvedOrigin,
113					resolvedDestination,
114				);
115				if (summary) setRouteSummary(summary);
116				setActive(null);
117				return true;
118			} catch (e) {
119				console.error("Failed to show route:", e);
120				return false;
121			}
122		}, [resolvedOrigin, resolvedDestination, mapRef]);
123	
124		const startNavigation = useCallback(async () => {
125			if (!resolvedOrigin || !resolvedDestination) return false;
126			try {
127				await mapRef.current?.startGuidance(resolvedOrigin, resolvedDestination);
128				setIsNavigating(true);
129				setActive(null);
130				return true;
131			} catch (e) {
132				console.error("Failed to start guidance:", e);
133				return false;
134			}
135		}, [resolvedOrigin, resolvedDestination, mapRef]);
136	
137		const stopNavigation = useCallback(async () => {
138			try {
139				await mapRef.current?.stopGuidance();
140			} finally {
141				setIsNavigating(false);
142			}
143		}, [mapRef]);
144	
145		const clearRoute = useCallback(() => {
146			mapRef.current?.clearRoute();
147			setRouteSummary(null);
148			setDestination(null);
149			setActive("destination");
150		}, [mapRef]);
151	
152		return {
153			query: search.query,
154			setQuery: search.setQuery,
155			results: search.results,
156			isLoading: search.isLoading,
157			hasSearched: search.hasSearched,
158			clear: search.clear,
159			origin,
160			destination,
161			active,
162			resolvedOrigin,
163			resolvedDestination,
164			canRoute,
165			routeSummary,
166			isNavigating,
167			userLocation,
168			editField,
169			selectResult,
170			setFieldToCurrent,
171			clearField,
172			swap,
173			confirmRoute,
174			startNavigation,
175			stopNavigation,
176			clearRoute,
177		};
178	}
