56	const SOFT_SPRING = {
57		damping: 28,
58		stiffness: 180,
59		mass: 1,
60		overshootClamping: false,
61		restSpeedThreshold: 0.01,
62		restDisplacementThreshold: 0.01,
63	} as const;
64	
65	type SheetProps = {
66		initialIndex?: number;
67		onIndexChange?: (index: number) => void;
68		children: React.ReactNode;
69		snapPoints?: Snap[];
70		className?: string;
71	};
72	
73	export function Sheet({
74		initialIndex = 0,
75		onIndexChange,
76		children,
77		snapPoints = ["peek", "half", "full"],
78		className,
79	}: SheetProps) {
