import { Text } from "@/components/ui/text";
import { cn } from "@/lib/utils";
import BottomSheet, {
	BottomSheetScrollView,
	useBottomSheet,
} from "@gorhom/bottom-sheet";
import type { ContainerLayoutState } from "@gorhom/bottom-sheet/lib/typescript/types";
import type React from "react";
import {
	createContext,
	useCallback,
	useContext,
	useEffect,
	useMemo,
	useRef,
	useState,
} from "react";
import { useColorScheme, View } from "react-native";
import Animated, {
	Extrapolation,
	interpolate,
	type SharedValue,
	useAnimatedStyle,
	useSharedValue,
} from "react-native-reanimated";
import {
	useSafeAreaFrame,
	useSafeAreaInsets,
} from "react-native-safe-area-context";

type SheetContextType = {
	index: number;
	lastIndex: number;
	animatedIndex: SharedValue<number>;
	snapTo: (i: number) => void;
	expand: () => void;
	collapse: () => void;
	toggle: () => void;
};
const SheetContext = createContext<SheetContextType | null>(null);

export function useSheet() {
	const ctx = useContext(SheetContext);
	if (!ctx) throw new Error("useSheet must be used within a <Sheet>");
	return ctx;
}

type Snap = "peek" | "half" | "full";

const SNAP_MAP: Record<Snap, string | number> = {
	peek: 160,
	half: "55%",
	full: "92%",
};

const SOFT_SPRING = {
	damping: 28,
	stiffness: 180,
	mass: 1,
	overshootClamping: false,
	restSpeedThreshold: 0.01,
	restDisplacementThreshold: 0.01,
} as const;

type SheetProps = {
	initialIndex?: number;
	onIndexChange?: (index: number) => void;
	children: React.ReactNode;
	snapPoints?: Snap[];
	className?: string;
};

export function Sheet({
	initialIndex = 0,
	onIndexChange,
	children,
	snapPoints = ["peek", "half", "full"],
	className,
}: SheetProps) {
	const ref = useRef<BottomSheet>(null);
	const scheme = useColorScheme();
	const isDark = scheme === "dark";
	const [index, setIndexState] = useState(initialIndex);
	const animatedIndex = useSharedValue(initialIndex);
	const insets = useSafeAreaInsets();
	const frame = useSafeAreaFrame();

	const containerLayout = useSharedValue<ContainerLayoutState>({
		height: frame.height,
		offset: { top: 0, left: 0, right: 0, bottom: 0 },
	});

	useEffect(() => {
		containerLayout.value = {
			height: frame.height,
			offset: { top: 0, left: 0, right: 0, bottom: 0 },
		};
	}, [frame.height, containerLayout]);

	const snapString = snapPoints.join(",");

	const points = useMemo(
		() => snapString.split(",").map((p) => SNAP_MAP[p as Snap] ?? "55%"),
		[snapString],
	);

	const lastIndex = points.length - 1;

	const handleChange = useCallback((i: number) => {
		setIndexState(i);
	}, []);

	useEffect(() => {
		onIndexChange?.(index);
	}, [index, onIndexChange]);

	const snapTo = useCallback((i: number) => ref.current?.snapToIndex(i), []);
	const expand = useCallback(
		() => ref.current?.snapToIndex(lastIndex),
		[lastIndex],
	);
	const collapse = useCallback(() => ref.current?.snapToIndex(0), []);
	const toggle = useCallback(() => {
		ref.current?.snapToIndex(index === 0 ? 1 : 0);
	}, [index]);

	const ctx = useMemo(
		() => ({
			index,
			lastIndex,
			animatedIndex,
			snapTo,
			expand,
			collapse,
			toggle,
		}),
		[index, lastIndex, animatedIndex, snapTo, expand, collapse, toggle],
	);

	return (
		<SheetContext.Provider value={ctx}>
			<BottomSheet
				ref={ref}
				index={initialIndex}
				animatedIndex={animatedIndex}
				snapPoints={points}
				containerLayoutState={containerLayout}
				topInset={insets.top}
				onChange={handleChange}
				animationConfigs={SOFT_SPRING}
				enablePanDownToClose={false}
				enableOverDrag
				overDragResistanceFactor={2.5}
				enableDynamicSizing={false}
				handleIndicatorStyle={{
					backgroundColor: isDark ? "#6b7280" : "#9ca3af",
					width: 44,
					height: 5,
					borderRadius: 999,
				}}
				backgroundStyle={{
					backgroundColor: isDark ? "#0b0b0f" : "#ffffff",
					borderTopLeftRadius: 28,
					borderTopRightRadius: 28,
				}}
				handleStyle={{
					backgroundColor: isDark ? "#0b0b0f" : "#ffffff",
					borderTopLeftRadius: 28,
					borderTopRightRadius: 28,
				}}
			>
				<View
					style={{ flex: 1, paddingBottom: insets.bottom }}
					className={className}
				>
					{children}
				</View>
			</BottomSheet>
		</SheetContext.Provider>
	);
}

function useFadeStyle(from: number, to: number, translate: number) {
	const { animatedIndex } = useBottomSheet();
	return useAnimatedStyle(() => {
		const opacity = interpolate(
			animatedIndex.value,
			[from - 0.5, from, to, to + 0.5],
			[0, 1, 1, 0],
			Extrapolation.CLAMP,
		);
		const ty = interpolate(
			animatedIndex.value,
			[from - 0.5, from],
			[translate, 0],
			Extrapolation.CLAMP,
		);
		return { opacity, transform: [{ translateY: ty }] };
	});
}

export function SheetPeek({
	children,
	translate = 8,
	className,
}: {
	children: React.ReactNode;
	translate?: number;
	className?: string;
}) {
	const { index } = useSheet();
	const style = useFadeStyle(0, 0, translate);
	const collapsed = index <= 0;

	return (
		<Animated.View
			style={style}
			pointerEvents={collapsed ? "auto" : "none"}
			className={cn(
				"absolute inset-x-0 top-0 z-10 w-full px-6 py-3",
				className,
			)}
		>
			{children}
		</Animated.View>
	);
}

export function SheetExpanded({
	children,
	translate = 16,
	className,
}: {
	children: React.ReactNode;
	translate?: number;
	className?: string;
}) {
	const { index, lastIndex } = useSheet();
	const style = useFadeStyle(1, lastIndex, translate);
	const expanded = index >= 1;

	return (
		<BottomSheetScrollView
			contentContainerStyle={{ paddingBottom: 32 }}
			showsVerticalScrollIndicator={false}
			scrollEnabled={expanded}
			pointerEvents={expanded ? "auto" : "none"}
		>
			<Animated.View
				style={style}
				className={cn("px-6 gap-4 w-full", className)}
			>
				{children}
			</Animated.View>
		</BottomSheetScrollView>
	);
}

export function SheetReveal({
	children,
	range,
	translate = 12,
	className,
}: {
	children: React.ReactNode;
	range: [number, number];
	translate?: number;
	className?: string;
}) {
	const [from, to] = range;
	const style = useFadeStyle(from, to, translate);

	return (
		<Animated.View style={style} className={className} pointerEvents="box-none">
			{children}
		</Animated.View>
	);
}

export function SheetTitle({ children }: { children: React.ReactNode }) {
	return (
		<Text className="text-xl font-semibold text-foreground">{children}</Text>
	);
}

export function SheetDescription({ children }: { children: React.ReactNode }) {
	return <Text className="text-sm text-muted-foreground">{children}</Text>;
}

export function SheetFooter({ children }: { children: React.ReactNode }) {
	return <Animated.View className="mt-6 gap-3">{children}</Animated.View>;
}

