import * as Location from "expo-location";
import type { LatLng } from "expo-here-maps";
import { useEffect, useState } from "react";

/**
 * Returns the user's current LatLng, preferring the last-known position
 * for speed then falling back to a fresh fix. Watches for updates while
 * the component is mounted.
 */
export function useCurrentLocation(): LatLng | null {
	const [location, setLocation] = useState<LatLng | null>(null);

	useEffect(() => {
		let active = true;
		let subscription: Location.LocationSubscription | null = null;

		const fetch = async () => {
			try {
				const lastKnown = await Location.getLastKnownPositionAsync();
				if (lastKnown && active) {
					setLocation({
						lat: lastKnown.coords.latitude,
						lng: lastKnown.coords.longitude,
					});
					return;
				}

				const current = await Location.getCurrentPositionAsync({
					accuracy: Location.Accuracy.Balanced,
				});
				if (active) {
					setLocation({
						lat: current.coords.latitude,
						lng: current.coords.longitude,
					});
				}
			} catch {
				if (active) setLocation(null);
			}
		};

		fetch();

		Location.watchPositionAsync(
			{ accuracy: Location.Accuracy.Balanced, distanceInterval: 100 },
			(pos) => {
				if (active) {
					setLocation({
						lat: pos.coords.latitude,
						lng: pos.coords.longitude,
					});
				}
			},
		)
			.then((sub) => {
				if (active) subscription = sub;
			})
			.catch(() => {});

		return () => {
			active = false;
			subscription?.remove();
		};
	}, []);

	return location;
}

