import * as Location from "expo-location";
import type { LocationPermissionResult } from "./types";

export async function checkLocationPermission(): Promise<LocationPermissionResult> {
	const fg = await Location.getForegroundPermissionsAsync();

	if (fg.status !== Location.PermissionStatus.GRANTED) {
		if (!fg.canAskAgain && fg.status === Location.PermissionStatus.DENIED) {
			return { state: "blocked", canAskAgain: false };
		}
		return {
			state: fg.status === Location.PermissionStatus.DENIED ? "denied" : "undetermined",
			canAskAgain: fg.canAskAgain,
		};
	}

	const bg = await Location.getBackgroundPermissionsAsync();
	if (bg.status === Location.PermissionStatus.GRANTED) {
		return { state: "granted", canAskAgain: true };
	}
	return { state: "foreground-only", canAskAgain: bg.canAskAgain };
}

export async function requestLocationPermission(): Promise<LocationPermissionResult> {
	const fg = await Location.requestForegroundPermissionsAsync();

	if (fg.status !== Location.PermissionStatus.GRANTED) {
		if (!fg.canAskAgain) {
			return { state: "blocked", canAskAgain: false };
		}
		return { state: "denied", canAskAgain: fg.canAskAgain };
	}

	const bg = await Location.requestBackgroundPermissionsAsync();
	if (bg.status === Location.PermissionStatus.GRANTED) {
		return { state: "granted", canAskAgain: true };
	}

	if (!bg.canAskAgain) {
		return { state: "foreground-only", canAskAgain: false };
	}
	return { state: "foreground-only", canAskAgain: bg.canAskAgain };
}

