import type React from "react";
import { useCallback } from "react";
import { View } from "react-native";
import { useSafeAreaInsets } from "react-native-safe-area-context";
import { useLocationPermission } from "../use-location-permission";
import { LocationGateContent } from "./LocationGateContent";

export function LocationGate({ children }: { children: React.ReactNode }) {
	const { state, canAskAgain, isChecking, isGranted, request, openSettings } =
		useLocationPermission();
	const insets = useSafeAreaInsets();

	const handleAction = useCallback(() => {
		if (state === "blocked") return openSettings();
		if (state === "foreground-only" && !canAskAgain) return openSettings();
		request();
	}, [state, canAskAgain, request, openSettings]);

	if (isChecking) return <View className="flex-1 bg-background" />;

	if (isGranted) return <>{children}</>;

	return (
		<View
			className="flex-1 bg-background"
			style={{ paddingTop: insets.top + 12, paddingBottom: insets.bottom + 8 }}
		>
			<LocationGateContent
				state={state}
				canAskAgain={canAskAgain}
				onAction={handleAction}
			/>
		</View>
	);
}

import {
	Bell,
	ChevronRight,
	Lock,
	MapPin,
	MapPinOff,
	Navigation,
	Settings,
	ShieldCheck,
} from "lucide-react-native";
import type React from "react";
import { ActivityIndicator, Platform, Pressable, Text, View } from "react-native";
import Animated, { FadeIn, FadeInDown, FadeInUp } from "react-native-reanimated";
import type { LocationPermissionState } from "../types";

type Benefit = { key: string; icon: React.ReactNode; label: string };
type Step = { key: string; label: string };

type Copy = {
	icon: React.ReactNode;
	tone: "brand" | "alert";
	eyebrow: string;
	title: string;
	body: string;
	benefits: Benefit[];
	steps: Step[];
	action: string | null;
	usesSettings: boolean;
};

const CHECKPOINT_BENEFITS: Benefit[] = [
	{ key: "alerts", icon: <Bell size={20} className="text-primary" />, label: "Live alerts for DVSA & VOSA checkpoints near you" },
	{ key: "route", icon: <Navigation size={20} className="text-primary" />, label: "Route guidance that helps you avoid delays" },
	{ key: "background", icon: <MapPin size={20} className="text-primary" />, label: "Stay alerted with the screen off while you drive" },
];

const ios = Platform.OS === "ios";

const SETTINGS_STEPS_ALWAYS: Step[] = ios
	? [
			{ key: "1", label: "Tap “Location” on the screen that opens" },
			{ key: "2", label: "Choose “Always”" },
			{ key: "3", label: "Return to UKcheckpoints" },
		]
	: [
			{ key: "1", label: "Tap “Permissions”, then “Location”" },
			{ key: "2", label: "Choose “Allow all the time”" },
			{ key: "3", label: "Return to UKcheckpoints" },
		];

const SETTINGS_STEPS_ENABLE: Step[] = ios
	? [
			{ key: "1", label: "Tap “Location” on the screen that opens" },
			{ key: "2", label: "Choose “While Using the App” or “Always”" },
			{ key: "3", label: "Return to UKcheckpoints" },
		]
	: [
			{ key: "1", label: "Tap “Permissions”, then “Location”" },
			{ key: "2", label: "Choose “Allow”" },
			{ key: "3", label: "Return to UKcheckpoints" },
		];

function copyFor(state: LocationPermissionState, canAskAgain: boolean): Copy {
	switch (state) {
		case "undetermined":
			return {
				icon: <MapPin size={36} className="text-primary" />,
				tone: "brand",
				eyebrow: "Location access",
				title: "Drive smarter, not harder",
				body: "UKcheckpoints uses your location to surface checkpoints and police activity on your route in real time.",
				benefits: CHECKPOINT_BENEFITS,
				steps: [],
				action: "Enable location",
				usesSettings: false,
			};
		case "foreground-only":
			return {
				icon: <Navigation size={36} className="text-primary" />,
				tone: "brand",
				eyebrow: "One more step",
				title: "Allow location all the time",
				body: canAskAgain
					? "You've allowed location while using the app. Set it to “Always” so alerts keep working with your phone in the cradle and the screen off."
					: "Alerts need location access set to “Always”. Open Settings and follow the steps below.",
				benefits: canAskAgain
					? [
							{ key: "bg-alerts", icon: <Bell size={20} className="text-primary" />, label: "Background alerts the moment a checkpoint appears" },
							{ key: "anonymous", icon: <Lock size={20} className="text-primary" />, label: "Anonymous — your location is never shared with other drivers" },
						]
					: [],
				steps: canAskAgain ? [] : SETTINGS_STEPS_ALWAYS,
				action: canAskAgain ? "Allow always" : "Open Settings",
				usesSettings: !canAskAgain,
			};
		case "denied":
			return {
				icon: <MapPinOff size={36} className="text-destructive" />,
				tone: "alert",
				eyebrow: "Location off",
				title: "We can't show your route",
				body: "Without location, the live map and checkpoint alerts can't work. Allow access to continue.",
				benefits: [],
				steps: [],
				action: "Try again",
				usesSettings: false,
			};
		case "blocked":
			return {
				icon: <Settings size={36} className="text-destructive" />,
				tone: "alert",
				eyebrow: "Location off",
				title: "Turn location back on",
				body: "Location is switched off for UKcheckpoints in your device settings. Open Settings and follow the steps below.",
				benefits: [],
				steps: SETTINGS_STEPS_ENABLE,
				action: "Open Settings",
				usesSettings: true,
			};
		case "checking":
		case "requesting":
			return {
				icon: <ActivityIndicator size="large" />,
				tone: "brand",
				eyebrow: "",
				title: "Waiting for permission",
				body: "Respond to the system prompt to continue.",
				benefits: [],
				steps: [],
				action: null,
				usesSettings: false,
			};
		case "granted":
			return {
				icon: <ShieldCheck size={36} className="text-primary" />,
				tone: "brand",
				eyebrow: "",
				title: "You're all set",
				body: "Loading the live map…",
				benefits: [],
				steps: [],
				action: null,
				usesSettings: false,
			};
	}
}

function BenefitCard({ benefits }: { benefits: Benefit[] }) {
	return (
		<View className="overflow-hidden rounded-2xl border border-border bg-card">
			{benefits.map((b, i) => (
				<View
					key={b.key}
					className={`flex-row items-center gap-4 px-4 py-3.5 ${
						i < benefits.length - 1 ? "border-b border-border" : ""
					}`}
				>
					<View className="h-9 w-9 items-center justify-center rounded-full bg-primary/10">
						{b.icon}
					</View>
					<Text className="flex-1 text-[15px] leading-snug text-foreground">
						{b.label}
					</Text>
				</View>
			))}
		</View>
	);
}

function StepsCard({ steps }: { steps: Step[] }) {
	return (
		<View className="overflow-hidden rounded-2xl border border-border bg-card">
			{steps.map((s, i) => (
				<View
					key={s.key}
					className={`flex-row items-center gap-4 px-4 py-3.5 ${
						i < steps.length - 1 ? "border-b border-border" : ""
					}`}
				>
					<View className="h-7 w-7 items-center justify-center rounded-full bg-foreground">
						<Text className="text-sm font-bold text-background">{s.key}</Text>
					</View>
					<Text className="flex-1 text-[15px] leading-snug text-foreground">
						{s.label}
					</Text>
				</View>
			))}
		</View>
	);
}

export function LocationGateContent({
	state,
	canAskAgain,
	onAction,
}: {
	state: LocationPermissionState;
	canAskAgain: boolean;
	onAction: () => void;
}) {
	const copy = copyFor(state, canAskAgain);
	const alert = copy.tone === "alert";

	return (
		<View className="flex-1 justify-between">
			<Animated.View
				entering={FadeIn.duration(260)}
				className="flex-1 justify-center gap-7 px-6"
			>
				<View className="gap-5">
					<Animated.View entering={FadeInDown.duration(300)}>
						<View
							className={`h-16 w-16 items-center justify-center rounded-2xl ${
								alert ? "bg-destructive/10" : "bg-primary/10"
							}`}
						>
							{copy.icon}
						</View>
					</Animated.View>

					<Animated.View
						entering={FadeInDown.duration(300).delay(60)}
						className="gap-2"
					>
						{copy.eyebrow ? (
							<Text className="text-[13px] font-semibold uppercase tracking-widest text-muted-foreground">
								{copy.eyebrow}
							</Text>
						) : null}
						<Text className="text-[30px] font-bold leading-[1.1] tracking-tight text-foreground">
							{copy.title}
						</Text>
						<Text className="text-[15px] leading-relaxed text-muted-foreground">
							{copy.body}
						</Text>
					</Animated.View>
				</View>

				{copy.benefits.length > 0 ? (
					<Animated.View entering={FadeInDown.duration(300).delay(120)}>
						<BenefitCard benefits={copy.benefits} />
					</Animated.View>
				) : null}

				{copy.steps.length > 0 ? (
					<Animated.View
						entering={FadeInDown.duration(300).delay(120)}
						className="gap-3"
					>
						<Text className="text-[13px] font-semibold uppercase tracking-widest text-muted-foreground">
							{ios ? "In Settings" : "In App info"}
						</Text>
						<StepsCard steps={copy.steps} />
					</Animated.View>
				) : null}
			</Animated.View>

			{copy.action ? (
				<Animated.View
					entering={FadeInUp.duration(300).delay(160)}
					className="gap-3 px-6 pb-2"
				>
					{!alert && state === "undetermined" ? (
						<View className="flex-row items-center justify-center gap-1.5">
							<Lock size={13} className="text-muted-foreground" />
							<Text className="text-center text-[13px] text-muted-foreground">
								Anonymous and secure. Never shared with other drivers.
							</Text>
						</View>
					) : null}

					<Pressable onPress={onAction} className="active:opacity-90">
						<View
							className={`flex-row items-center justify-center gap-2 rounded-2xl py-4 ${
								alert ? "bg-destructive" : "bg-primary"
							}`}
						>
							{copy.usesSettings ? (
								<Settings size={19} className={alert ? "text-destructive-foreground" : "text-primary-foreground"} />
							) : null}
							<Text
								className={`text-[16px] font-semibold ${
									alert ? "text-destructive-foreground" : "text-primary-foreground"
								}`}
							>
								{copy.action}
							</Text>
							{!copy.usesSettings && !alert ? (
								<ChevronRight size={18} className="text-primary-foreground opacity-70" />
							) : null}
						</View>
					</Pressable>
				</Animated.View>
			) : null}
		</View>
	);
}

