                    onNavigableLocation(mapOf("streetName" to streetName, "speedLimit" to speedLimit))
                }
            })

            addView(mv, FrameLayout.LayoutParams(
                FrameLayout.LayoutParams.MATCH_PARENT,
                FrameLayout.LayoutParams.MATCH_PARENT
            ))
        } catch (e: CodedException) {
            Log.e(TAG, "[${e.code}] ${e.message}", e.cause)
            onMapError(mapOf("code" to e.code, "message" to (e.message ?: "Unknown init error")))
        } catch (e: Exception) {
            Log.e(TAG, "[E_VIEW_INIT] ${e.message}", e)
            onMapError(mapOf("code" to "E_VIEW_INIT", "message" to (e.message ?: "Failed to create HERE Maps view")))
        }
    }

    fun setMapCenter(lat: Double, lng: Double, animated: Boolean = false, distanceMeters: Double? = null) {
        if (!ready) {
            pendingCenter = Triple(lat, lng, animated)
            pendingDistanceMeters = distanceMeters
            return
        }
        val mv = mapView ?: return
        val coords = GeoCoordinates(lat, lng)
        if (animated) {
            val update = GeoCoordinatesUpdate(coords)
            val anim = MapCameraAnimationFactory.flyTo(update, 1.0, Duration.ofSeconds(1))
            mv.camera.startAnimation(anim)
        } else if (distanceMeters != null) {
            mv.camera.lookAt(coords, MapMeasure(MapMeasure.Kind.DISTANCE_IN_METERS, distanceMeters))
        } else {
            mv.camera.lookAt(coords)
        }
    }

    fun setBearing(bearing: Double) {
        if (!ready) { pendingBearing = bearing; return }
        val mv = mapView ?: return
        val state = mv.camera.state
        mv.camera.setOrientationAtTarget(GeoOrientationUpdate(bearing, state.orientationAtTarget.tilt))
    }

    fun setTilt(tilt: Double) {
        if (!ready) { pendingTilt = tilt; return }
        val mv = mapView ?: return
        val state = mv.camera.state
        mv.camera.setOrientationAtTarget(GeoOrientationUpdate(state.orientationAtTarget.bearing, tilt))
    }

    fun onResume() { mapView?.onResume() }
    fun onPause() { mapView?.onPause() }

    fun updateUserLocation(lat: Double, lng: Double, bearing: Double?) {
        if (!::locationIndicator.isInitialized) return
        val location = Location(GeoCoordinates(lat, lng))
        bearing?.let { location.bearingInDegrees = it }
        locationIndicator.updateLocation(location)
        locationIndicator.isActive = true
    }

    private fun seedLastKnownLocation() {
        try {
            val lm = context.getSystemService(Context.LOCATION_SERVICE) as LocationManager
            val providers = listOf(
                LocationManager.GPS_PROVIDER,
                LocationManager.NETWORK_PROVIDER,
                LocationManager.FUSED_PROVIDER
            )
            for (provider in providers) {
                val lastKnown = lm.getLastKnownLocation(provider) ?: continue
                val location = Location(GeoCoordinates(lastKnown.latitude, lastKnown.longitude))
                if (lastKnown.bearing != 0f) location.bearingInDegrees = lastKnown.bearing.toDouble()
                locationIndicator.updateLocation(location)
                locationIndicator.isActive = true
                break
            }
        } catch (e: SecurityException) {
            log("Location permission not granted, skipping seed")
        } catch (e: Exception) {
            log("Seed failed: ${e.message}")
        }
    }

    fun onDestroy() {
        ready = false
        if (::guidanceManager.isInitialized) guidanceManager.stopGuidance()
        if (::routeManager.isInitialized) routeManager.clearRoute()
        if (::locationIndicator.isInitialized) locationIndicator.disable()
        mapView?.let {
            it.onPause()
            it.onDestroy()
        }
        mapView = null
        controls.updateView(null)
    }

    private fun applyPending() {
        pendingCenter?.let { (lat, lng, animated) ->
            setMapCenter(lat, lng, animated, pendingDistanceMeters)
            pendingCenter = null
            pendingDistanceMeters = null
        }
        pendingBearing?.let { setBearing(it); pendingBearing = null }
        pendingTilt?.let { setTilt(it); pendingTilt = null }
    }

    private fun initEngine(context: Context) {
        if (SDKNativeEngine.getSharedInstance() != null) return

        val appInfo = context.packageManager.getApplicationInfo(context.packageName, PackageManager.GET_META_DATA)
        val bundle = appInfo.metaData
        val accessKeyID = bundle?.getString("HERE_ACCESS_KEY_ID") ?: ""
        val accessKeySecret = bundle?.getString("HERE_ACCESS_KEY_SECRET") ?: ""

        if (accessKeyID.isEmpty() || accessKeySecret.isEmpty()) {
            throw CodedException(
                "E_NO_CREDENTIALS",
                "HERE SDK credentials missing from AndroidManifest. Check .env has HERE_ACCESS_KEY_ID and HERE_ACCESS_KEY_SECRET, then run: bunx expo prebuild --clean",
                null
            )
        }

        try {
            SDKNativeEngine.makeSharedInstance(
                context,
                SDKOptions(AuthenticationMode.withKeySecret(accessKeyID, accessKeySecret))
            )
        } catch (e: Exception) {
            throw CodedException("E_ENGINE_INIT", "Failed to initialize HERE SDK engine — likely invalid or expired credentials: ${e.message}", e)
        }
    }

    private fun log(msg: String) { Log.i(TAG, msg) }
}

import { useRouteState } from "@/features/navigation/route-context";
import { formatManeuverDistance } from "@/features/navigation/lib/format-route";
import {
	ArrowLeft,
	ArrowRight,
	ArrowUp,
	ArrowUpLeft,
	ArrowUpRight,
	CornerDownLeft,
	CornerDownRight,
	MapPin,
	Navigation,
	RotateCcw,
	RotateCw,
} from "lucide-react-native";
import type React from "react";
import { Text, View } from "react-native";
import Animated, { FadeInDown, FadeOutUp, LinearTransition } from "react-native-reanimated";
import { useSafeAreaInsets } from "react-native-safe-area-context";

function ManeuverIcon({ action }: { action: string }): React.ReactNode {
	const props = { size: 28, strokeWidth: 2.5, className: "text-primary-foreground" } as const;

	switch (action) {
		case "TURN_LEFT":
		case "SHARPLY_LEFT":
		case "LEFT_FORK":
		case "LEFT_RAMP":
		case "LEFT_EXIT":
		case "MOTORWAY_CHANGE_LEFT":
			return <ArrowLeft {...props} />;
		case "TURN_RIGHT":
		case "SHARPLY_RIGHT":
		case "RIGHT_FORK":
		case "RIGHT_RAMP":
		case "RIGHT_EXIT":
		case "MOTORWAY_CHANGE_RIGHT":
			return <ArrowRight {...props} />;
		case "SLIGHT_LEFT":
		case "KEEP_LEFT":
			return <ArrowUpLeft {...props} />;
		case "SLIGHT_RIGHT":
		case "KEEP_RIGHT":
			return <ArrowUpRight {...props} />;
		case "U_TURN_LEFT":
			return <RotateCcw {...props} />;
		case "U_TURN_RIGHT":
			return <RotateCw {...props} />;
		case "ROUNDABOUT_ENTER":
		case "ROUNDABOUT_EXIT":
		case "ROUNDABOUT_PASS":
			return <CornerDownRight {...props} />;
		case "ENTER_HIGHWAY":
			return <CornerDownLeft {...props} />;
		case "EXIT_HIGHWAY":
			return <CornerDownRight {...props} />;
		case "ARRIVE":
			return <MapPin {...props} />;
		case "DEPART":
			return <Navigation {...props} />;
		default:
			return <ArrowUp {...props} />;
	}
}

export function ManeuverBanner() {
	const { phase, maneuverText, maneuverAction, maneuverDistanceMeters } = useRouteState();
	const insets = useSafeAreaInsets();

	if (phase !== "navigating" || !maneuverText) return null;

	const distanceLabel =
		maneuverDistanceMeters != null && maneuverDistanceMeters > 50
			? formatManeuverDistance(maneuverDistanceMeters)
			: null;

	return (
		<Animated.View
			entering={FadeInDown.duration(300).springify()}
			exiting={FadeOutUp.duration(200)}
			layout={LinearTransition.springify()}
			style={{ top: insets.top + 12 }}
			className="absolute inset-x-4 z-50 overflow-hidden rounded-3xl bg-primary shadow-2xl"
		>
			<View className="flex-row items-center gap-4 px-5 py-4">
				<View className="h-14 w-14 items-center justify-center rounded-2xl bg-white/15">
					<ManeuverIcon action={maneuverAction ?? "CONTINUE"} />
				</View>

				<View className="flex-1 gap-0.5">
					{distanceLabel ? (
						<Text className="text-[13px] font-semibold uppercase tracking-wider text-primary-foreground/70">
							In {distanceLabel}
						</Text>
					) : null}
					<Text
						className="text-[17px] font-bold leading-snug text-primary-foreground"
						numberOfLines={2}
					>
						{maneuverText}
					</Text>
				</View>
			</View>
		</Animated.View>
	);
}

import { Sheet, SheetExpanded, SheetPeek } from "@/components/ui/sheet";
import { useCurrentLocation } from "@/features/location/use-current-location";
import { ArrivalScreen } from "@/features/navigation/components/ArrivalScreen";
import { ManeuverBanner } from "@/features/navigation/components/ManeuverBanner";
import { SheetSearch } from "@/features/navigation/components/SheetSearch";
import { SheetSearchDecoy } from "@/features/navigation/components/SheetSearchDecoy";
import { RouteStateProvider, useRouteState } from "@/features/navigation/route-context";
import type { GuidanceProgressEvent, HereMapsViewRef, ManeuverEvent } from "expo-here-maps";
import { HereMapsView } from "expo-here-maps";
import { LocateFixed } from "lucide-react-native";
import { useCallback, useEffect, useRef, useState } from "react";
import { StyleSheet, Text, View } from "react-native";
import Animated, {
	Easing,
	FadeOut,
	interpolate,
	useAnimatedStyle,
	useSharedValue,
	withDelay,
	withRepeat,
	withTiming,
} from "react-native-reanimated";
import { useSafeAreaInsets } from "react-native-safe-area-context";

function PulseRing({ delay = 0 }: { delay?: number }) {
	const progress = useSharedValue(0);

	useEffect(() => {
		progress.value = withDelay(
			delay,
			withRepeat(
				withTiming(1, { duration: 1800, easing: Easing.out(Easing.quad) }),
				-1,
			),
		);
	}, [delay, progress]);

	const style = useAnimatedStyle(() => ({
		opacity: interpolate(progress.value, [0, 0.4, 1], [0.5, 0.15, 0]),
		transform: [{ scale: interpolate(progress.value, [0, 1], [1, 2.6]) }],
	}));

	return (
		<Animated.View
			style={[style, { position: "absolute", width: 80, height: 80, borderRadius: 40 }]}
			className="bg-primary/25"
		/>
	);
}

function LocatingScreen() {
	const insets = useSafeAreaInsets();
	return (
		<View
			className="flex-1 items-center justify-center bg-background"
			style={{ paddingBottom: insets.bottom + 32 }}
		>
			<View className="h-48 w-48 items-center justify-center">
				<PulseRing delay={0} />
				<PulseRing delay={700} />
				<View className="h-20 w-20 items-center justify-center rounded-full bg-primary/10">
					<LocateFixed size={34} className="text-primary" strokeWidth={2} />
				</View>
			</View>
			<View className="items-center gap-2">
				<Text className="text-[19px] font-semibold text-foreground">Finding your location</Text>
				<Text className="text-[15px] text-muted-foreground">This just takes a moment</Text>
			</View>
		</View>
	);
}

function MapScreen() {
	const mapRef = useRef<HereMapsViewRef>(null);
	const location = useCurrentLocation();
	const [located, setLocated] = useState(false);
	const didCenter = useRef(false);
	const { set } = useRouteState();

	useEffect(() => {
		if (location && !didCenter.current) {
			didCenter.current = true;
			mapRef.current?.setCameraPosition({
				lat: location.lat,
				lng: location.lng,
				distanceMeters: 800,
			});
			setLocated(true);
		}
	}, [location]);

	const handleGuidanceProgress = useCallback(
		(e: { nativeEvent: GuidanceProgressEvent }) => {
			set({
				remainingMeters: e.nativeEvent.remainingMeters,
				etaSeconds: e.nativeEvent.etaSeconds,
			});
		},
		[set],
	);

	const handleManeuver = useCallback(
		(e: { nativeEvent: ManeuverEvent }) => {
			set({
				maneuverText: e.nativeEvent.text,
				maneuverAction: e.nativeEvent.action,
				maneuverDistanceMeters: e.nativeEvent.distanceMeters,
			});
		},
		[set],
	);

	const handleArrived = useCallback(() => {
		set({ phase: "arrived" });
	}, [set]);

	return (
		<View style={{ flex: 1 }}>
			<HereMapsView
				ref={mapRef}
				style={StyleSheet.absoluteFill}
				bearing={0}
				tilt={0}
				onGuidanceProgress={handleGuidanceProgress}
				onManeuver={handleManeuver}
				onArrived={handleArrived}
			/>

			<ManeuverBanner />

			<Sheet snapPoints={["peek", "half", "full"]}>
				<SheetPeek>
					<SheetSearchDecoy />
				</SheetPeek>
				<SheetExpanded>
					<SheetSearch mapRef={mapRef} />
				</SheetExpanded>
			</Sheet>

			<ArrivalScreen />

			{!located ? (
				<Animated.View exiting={FadeOut.duration(400)} style={StyleSheet.absoluteFill}>
					<LocatingScreen />
				</Animated.View>
			) : null}
		</View>
	);
}

export default function Home() {
	return (
		<RouteStateProvider>
			<MapScreen />
		</RouteStateProvider>
	);
}

import { useRouteState } from "@/features/navigation/route-context";
import { MapPin } from "lucide-react-native";
import { useEffect } from "react";
import { Text, View } from "react-native";
import Animated, { FadeIn, FadeOut } from "react-native-reanimated";
import { useSafeAreaInsets } from "react-native-safe-area-context";

const DISMISS_MS = 3200;

export function ArrivalScreen() {
	const { phase, stopNavigation } = useRouteState();
	const insets = useSafeAreaInsets();

	useEffect(() => {
		if (phase !== "arrived") return;
		const t = setTimeout(() => stopNavigation(), DISMISS_MS);
		return () => clearTimeout(t);
	}, [phase, stopNavigation]);

	if (phase !== "arrived") return null;

	return (
		<Animated.View
			entering={FadeIn.duration(300)}
			exiting={FadeOut.duration(400)}
			className="absolute inset-0 items-center justify-center bg-background/90"
			style={{ paddingBottom: insets.bottom + 32 }}
		>
			<Animated.View
				entering={FadeIn.duration(400).delay(80)}
				className="items-center gap-5"
			>
				<View className="h-24 w-24 items-center justify-center rounded-full bg-primary/10">
					<MapPin size={46} className="text-primary" strokeWidth={1.75} />
				</View>
				<View className="items-center gap-2">
					<Text className="text-[30px] font-bold tracking-tight text-foreground">
						You've arrived
					</Text>
					<Text className="text-[16px] text-muted-foreground">
						You've reached your destination
					</Text>
				</View>
			</Animated.View>
		</Animated.View>
	);
}

