		registerStopNavigation(stopNavigation);
	}, [registerStopNavigation, stopNavigation]);

	return {
		query: search.query,
		setQuery: search.setQuery,
		results: search.results,
		isLoading: search.isLoading,
		hasSearched: search.hasSearched,
		clear: search.clear,
		origin,
		destination,
		active,
		resolvedOrigin,
		resolvedDestination,
		canRoute,
		isStartingNavigation,
		userLocation,
		editField,
		selectResult,
		setFieldToCurrent,
		clearField,
		swap,
		startNavigation,
		stopNavigation,
	};
}

